from typing import List

class Solution:
    def earliestSecondToMarkIndices(self, nums: List[int], changeIndices: List[int]) -> int:
        n = len(nums)
        m = len(changeIndices)

        def check(time):
            last_occurrence = {}
            for i in range(n):
                last_occurrence[i + 1] = -1

            for i in range(time):
                last_occurrence[changeIndices[i]] = i

            for i in range(1, n + 1):
                if last_occurrence[i] == -1:
                    return False

            marked = [False] * n
            operations = [0] * time

            for i in range(time):
                operations[i] = 0

            for i in range(1, n + 1):
                operations[last_occurrence[i]] = i

            temp_nums = nums[:]

            for i in range(time):
                if operations[i] == 0:
                    best_index = -1
                    for j in range(n):
                        if not marked[j]:
                            if best_index == -1 or temp_nums[j] > temp_nums[best_index]:
                                best_index = j

                    if best_index != -1:
                        temp_nums[best_index] = max(0, temp_nums[best_index] - 1)
                else:
                    index_to_mark = operations[i] - 1
                    if temp_nums[index_to_mark] == 0:
                        marked[index_to_mark] = True
                    else:
                        return False

            return all(marked)

        left = 1
        right = m
        ans = -1

        while left <= right:
            mid = (left + right) // 2
            if check(mid):
                ans = mid
                right = mid - 1
            else:
                left = mid + 1

        return ans
